import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/GET-DATA.md","filePath":"manual-en/GET-DATA.md","lastUpdated":1785684581000}'),o={name:"manual-en/GET-DATA.md"};function n(s,e,p,i,c,l){return a(),r("div",null,[...e[0]||(e[0]=[d(`<h3 id="_9-4-get-data" tabindex="-1">9.4 GET DATA <a class="header-anchor" href="#_9-4-get-data" aria-label="Permalink to &quot;9.4 GET DATA&quot;">​</a></h3><pre><code>GET DATA
        /TYPE={GNM,ODS,PSQL,TXT}
        …additional subcommands depending on TYPE…
</code></pre><p>The <code>GET DATA</code> command is used to read files and other data sources created by other applications. When this command is executed, the current dictionary and active dataset are replaced with variables and data read from the specified source.</p><p>The <code>TYPE</code> subcommand is mandatory and must be the first subcommand specified. It determines the type of the file or source to read. PSPP currently supports the following file types:</p><p>GNM</p><p>Spreadsheet files created by Gnumeric (<a href="http://gnumeric.org" target="_blank" rel="noreferrer">http://gnumeric.org</a>).</p><p>ODS</p><p>Spreadsheet files in OpenDocument format (<a href="http://opendocumentformat.org" target="_blank" rel="noreferrer">http://opendocumentformat.org</a>).</p><p>PSQL</p><p>Relations from PostgreSQL databases (<a href="http://postgresql.org" target="_blank" rel="noreferrer">http://postgresql.org</a>).</p><p>TXT</p><p>Textual data files in columnar and delimited formats.</p><p>Each supported file type has additional subcommands, explained in separate sections below.</p><table tabindex="0"><thead><tr><th>• GET DATA /TYPE=GNM/ODS</th><th></th><th>Spreadsheets</th></tr></thead><tbody><tr><td>• GET DATA /TYPE=PSQL</td><td></td><td>Databases</td></tr><tr><td>• GET DATA /TYPE=TXT</td><td></td><td>Delimited Text Files</td></tr></tbody></table>`,14)])])}const h=t(o,[["render",n]]);export{m as __pageData,h as default};
